// Secret scanning script to prevent accidental commit of secrets
const fs = require('fs');
const path = require('path');

// Patterns that might indicate secrets
const secretPatterns = [
  { name: 'AWS Access Key', pattern: /AKIA[0-9A-Z]{16}/ },
  { name: 'AWS Secret Key', pattern: /.*(?:aws|amazon).*?(?:secret|key).*?[=\s"']+(.{10,})/i },
  { name: 'Database URL', pattern: /.*(?:db|database|postgres|postgresql).*?[=\s"']+(.*@.*:\d+)/i },
  { name: 'Stripe Key', pattern: /sk_(live|test)_[0-9a-zA-Z]{24}/ },
  { name: 'API Key', pattern: /.*(?:api|token).*?[=\s"']+(.{20,})/i },
  { name: 'Private Key', pattern: /-----BEGIN (?:RSA )?PRIVATE KEY-----.+?-----END (?:RSA )?PRIVATE KEY-----/s },
  { name: 'Password', pattern: /.*(?:pass|pwd|password).*?[=\s"']+(.{4,})/i }
];

// Files to scan
const filesToScan = [
  'app.js',
  'config/',
  'middleware/',
  'scripts/',
  '.env.test',
  '.env',
  '.env.local',
  'package.json',
  'SECURITY.md'
];

// Files to exclude
const excludeFiles = [
  '.env.test' // This file contains test canary values intentionally
];

function scanFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    secretPatterns.forEach(({ name, pattern }) => {
      // Check each line separately to get line numbers
      lines.forEach((line, index) => {
        const trimmedLine = line.trim();
        if (pattern.test(trimmedLine) && !trimmedLine.includes('CANARY')) {
          console.log(`\x1b[33m${name} potentially exposed in ${filePath} at line ${index + 1}:\x1b[0m`);
          console.log(`  ${line.substring(0, 80)}${line.length > 80 ? '...' : ''}\n`);
        }
      });
    });
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
  }
}

function scanDirectory(dirPath) {
  try {
    const items = fs.readdirSync(dirPath);
    items.forEach(item => {
      const itemPath = path.join(dirPath, item);
      const stat = fs.statSync(itemPath);

      if (stat.isDirectory()) {
        scanDirectory(itemPath);
      } else {
        if (!excludeFiles.includes(path.basename(itemPath))) {
          scanFile(itemPath);
        }
      }
    });
  } catch (error) {
    console.error(`Error reading directory ${dirPath}:`, error.message);
  }
}

// Main execution
console.log('🔍 Scanning for potentially exposed secrets...\n');

filesToScan.forEach(file => {
  const fullPath = path.join(__dirname, '..', file);
  const stat = fs.existsSync(fullPath) ? fs.statSync(fullPath) : null;

  if (stat) {
    if (stat.isDirectory()) {
      scanDirectory(fullPath);
    } else {
      if (!excludeFiles.includes(path.basename(file))) {
        scanFile(fullPath);
      }
    }
  }
});

console.log('\x1b[32mScan complete. Check results above.\x1b[0m');
console.log('\x1b[33mNote: .env.test is excluded from scanning as it contains intentional test canaries.\x1b[0m');

