  it('should load canary database URL', () => {
    const dbUrl = secrets.getDatabaseUrl();
    expect(dbUrl).to.include('CANARY-db-secret');
    expect(dbUrl).to.include('postgres://');
  });

  it('should load canary AWS access key ID', () => {
