  });

  it('should load canary AWS secret key', () => {
    const secretKey = secrets.getAwsSecretKey();
    expect(secretKey).to.include('CANARY-aws-secret-key');
  });

  it('should load canary Anthropic API key', () => {
    const apiKey = secrets.getAnthropicApiKey();
    expect(apiKey).to.include('CANARY-api-key');
  });

  it('should load canary Stripe secret key', () => {
    const stripeKey = secrets.getStripeSecretKey();
    expect(stripeKey).to.include('CANARY-stripe-key');
  });

  it('should load canary Logfire token', () => {
    const token = secrets.getLogfireToken();
    expect(token).to.include('CANARY-logfire-token');
  });

  it('should log access when retrieving secrets', () => {
    // Redirect console.log to capture output
    const originalLog = console.log;
